package com.smartbank.model;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Standardized Threat Evaluation Result generated by SmartBank AI Explainable Risk Engine.
 */
public class ThreatResult {
    private String eventId;
    private int riskScore; // 0 - 100
    private String riskLevel; // LOW, MEDIUM, HIGH, CRITICAL
    private String threatType; // FRAUD, PHISHING, MALWARE, RANSOMWARE, ATO
    private List<String> signalsTriggered;
    private List<Map<String, Object>> signals;
    private String explanation;
    private String recommendedAction;

    public ThreatResult() {
        this.signalsTriggered = new ArrayList<>();
        this.signals = new ArrayList<>();
    }

    public ThreatResult(String eventId, int riskScore, String riskLevel, String explanation, String recommendedAction) {
        this.eventId = eventId;
        this.riskScore = Math.min(100, Math.max(0, riskScore));
        this.riskLevel = riskLevel;
        this.explanation = explanation;
        this.recommendedAction = recommendedAction;
        this.signalsTriggered = new ArrayList<>();
        this.signals = new ArrayList<>();
    }

    public String getEventId() { return eventId; }
    public void setEventId(String eventId) { this.eventId = eventId; }

    public int getRiskScore() { return riskScore; }
    public void setRiskScore(int riskScore) { this.riskScore = Math.min(100, Math.max(0, riskScore)); }
    public void setScore(int score) { setRiskScore(score); }

    public String getRiskLevel() { return riskLevel; }
    public void setRiskLevel(String riskLevel) { this.riskLevel = riskLevel; }

    public String getThreatType() { return threatType; }
    public void setThreatType(String threatType) { this.threatType = threatType; }

    public List<String> getSignalsTriggered() { return signalsTriggered; }
    public void setSignalsTriggered(List<String> signalsTriggered) { this.signalsTriggered = signalsTriggered; }

    public List<Map<String, Object>> getSignals() { return signals; }
    public void setSignals(List<Map<String, Object>> signals) { this.signals = signals; }

    public String getExplanation() { return explanation; }
    public void setExplanation(String explanation) { this.explanation = explanation; }

    public String getRecommendedAction() { return recommendedAction; }
    public void setRecommendedAction(String recommendedAction) { this.recommendedAction = recommendedAction; }
    public void setMitigationRecommendation(String recommendation) { this.recommendedAction = recommendation; }

    public void addSignal(String signal) {
        this.signalsTriggered.add(signal);
    }
}
